import boto3
from document_client import get_textract_client

def extract_layout(document_path):
    textract_client = get_textract_client()
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = textract_client.detect_document_text(Document={'Bytes': image_bytes})
    layout = {
        'blocks': [],
        'lines': [],
        'tables': []
    }
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            layout['lines'].append(item['Text'])
        elif item['BlockType'] == 'TABLE':
            layout['tables'].append(item)
        elif item['BlockType'] == 'KEY_VALUE_SET':
            layout['blocks'].append(item)
    return layout

import boto3
from document_client import get_textract_client

def extract_tables(document_path):
    textract_client = get_textract_client()
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = textract_client.analyze_document(Document={'Bytes': image_bytes}, FeatureTypes=['TABLES'])
    tables = []
    for table in response['Blocks']:
        if table['BlockType'] == 'TABLE':
            table_data = {
                'cells': [],
                'rows': []
            }
            for relationship in table['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        for block in response['Blocks']:
                            if block['Id'] == child_id:
                                if block['BlockType'] == 'CELL':
                                    table_data['cells'].append(block['Text'])
                                elif block['BlockType'] == 'ROW':
                                    table_data['rows'].append(block['Text'])
            tables.append(table_data)
    return tables

import boto3
from document_client import get_textract_client

def extract_key_values(document_path):
    textract_client = get_textract_client()
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = textract_client.analyze_document(Document={'Bytes': image_bytes}, FeatureTypes=['FORMS'])
    key_values = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'KEY' in block['EntityTypes']:
                key_values[block['Text']] = None
            elif 'VALUE' in block['EntityTypes']:
                key_values[list(key_values.keys())[-1]] = block['Text']
    return key_values

from typing import Dict, List

def normalize_text(text: str) -> str:
    return text.strip()

def normalize_layout(layout: Dict) -> Dict:
    return {
        'blocks': [normalize_text(block) for block in layout['blocks']],
        'lines': [normalize_text(line) for line in layout['lines']],
        'tables': layout['tables']
    }

def normalize_tables(tables: List[Dict]) -> List[Dict]:
    return [{'cells': [normalize_text(cell) for cell in table['cells']], 'rows': [normalize_text(row) for row in table['rows']]} for table in tables]

def normalize_key_values(key_values: Dict) -> Dict:
    return {normalize_text(key): normalize_text(value) for key, value in key_values.items()}

